"""Claude: order of the group generated by the six G34-BLOCK-01 reflections, via its faithful permutation action on
the orbit of the six roots (closure of vectors under the reflections)."""
import sys,json
sys.path.insert(0,'/home/claude/g34/h4sel/p2p3')
from generic_engine import *
from sympy.combinatorics import Permutation, PermutationGroup
J=json.load(open('G34_BLOCK_01_roots.json'))
R=[[ (F(a),F(b)) for a,b in v] for v in J['six_basis_roots']]
n=6
def refl(v):
    f=mul((F(-2),F(0)),inv(h(v,v)))
    return [[add(ONE if i==j else Z, mul(f,mul(v[i],conj(v[j])))) for j in range(n)] for i in range(n)]
S=[refl(v) for v in R]
print('root norms:',[h(v,v) for v in R],' K-rank of roots:',rank([list(v) for v in R]))
key=lambda v: tuple(x for c in v for x in c)
orb={key(v):v for v in R}; frontier=list(R)
while frontier:
    new=[]
    for v in frontier:
        for s in S:
            w=mv(s,v); k=key(w)
            if k not in orb: orb[k]=w; new.append(w)
    frontier=new
# close under unit multiples so action is on full vector set
units=[(F(1),F(0)),(F(0),F(1)),(F(-1),F(-1)),(F(-1),F(0)),(F(0),F(-1)),(F(1),F(1))]
allv={}
for v in orb.values():
    for u in units: w=vsc(u,v); allv[key(w)]=w
keys=list(allv); idx={k:i for i,k in enumerate(keys)}
print('vectors in closure (units included):',len(keys))
perms=[Permutation([idx[key(mv(s,allv[k]))] for k in keys]) for s in S]
G=PermutationGroup(perms)
print('group order (faithful on these vectors):',G.order())
